/* Session-only practice UI; question content comes from the signed-in catalog. */
(function(root){
 'use strict';
 const Q=root.WarPlannerPractice;
 const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let bankCache=null;
 let goal='army',selectedDetachment='',selectedFaction='',scope='faction',listId='',selectedTypes=['units','timing'],savedLists=[],activeListId='',length=10,session=null,bank=null,catalog=null,rules=null,error='';
 const modeLabels=()=>goal==='opponent'?Q.opponentModes:Q.modes;
 const focus=()=>document.querySelector('#practice-title')?.focus({preventScroll:true});
 const refresh=control=>{root.refreshWarPlannerContent?.();if(control){const field=[...document.querySelectorAll('#practice-setup [name]')].find(el=>el.name===control.name&&el.value===control.value);field?.focus({preventScroll:true});}else focus();};
 const normalized=value=>String(value||'').toLowerCase().replace(/[^a-z0-9]/g,'');
 function selectionBank(fresh=false){
  const army=goal==='army'&&scope==='list'?savedLists.find(list=>list.id===listId)?.army||{faction:selectedFaction,name:'Unavailable saved list',units:[]}:null;
  const faction=army?(catalog.factions||[]).find(f=>normalized(f.name)===normalized(army.faction)||(f.aliases||[]).some(a=>normalized(a)===normalized(army.faction)))?.name||army.faction:selectedFaction;
  const generation=root.WarPlannerContent?.generation,units=catalog.units,detachments=catalog.detachments;
  const key=Number.isInteger(generation)?JSON.stringify([generation,goal,faction,army,selectedDetachment]):null;
  if(!fresh&&key!==null&&bankCache?.key===key&&bankCache.rules===rules&&bankCache.units===units&&bankCache.detachments===detachments)return bankCache.bank;
  const next=(goal==='opponent'?Q.buildOpponentBank:Q.buildBank)({faction,army,rules,units,detachments:detachments||[],detachment:goal==='opponent'?selectedDetachment:''});
  bankCache=key===null?null:{key,rules,units,detachments,bank:next};return next;
 }
 function readSetup(form){
  const fd=new FormData(form),old=goal,oldFaction=selectedFaction;
  if(['army','opponent'].includes(fd.get('practice_goal')))goal=String(fd.get('practice_goal'));
  if(['list','faction'].includes(fd.get('practice_scope')))scope=String(fd.get('practice_scope'));
  if(fd.has('practice_faction'))selectedFaction=String(fd.get('practice_faction'));
  if(fd.has('practice_list'))listId=String(fd.get('practice_list'));
  if(fd.has('practice_detachment'))selectedDetachment=String(fd.get('practice_detachment'));
  if(selectedFaction!==oldFaction)selectedDetachment='';
  selectedTypes=fd.getAll('practice_modes').map(String);length=Number(fd.get('practice_length'));
  if(goal!==old){scope='faction';selectedDetachment='';selectedTypes=goal==='opponent'?['effects','timing','units']:['units','timing'];}
 }
 const scopeLabel=()=>session.perspective==='opponent'?'Opponent · '+session.faction+(session.detachment?' · '+session.detachment:' · All detachments'):session.scope==='list'?session.listName+' · '+session.faction:session.faction;
 function render(context){
  catalog=context.catalog;rules=context.rules;savedLists=Array.isArray(context.savedLists)?context.savedLists:[];activeListId=context.activeListId||'';
  // Only the standalone Aeldari prototype lacks catalog faction metadata.
  if(!catalog.factions){catalog={...catalog,units:catalog.units.map(u=>({...u,faction:u.faction||'Aeldari'}))};rules=rules.map(r=>({...r,faction:r.faction||'Aeldari'}));}
  if(session)return session.index>=session.questions.length?results():question();
  const factions=catalog.factions||[{name:'Aeldari',group:'Xenos'}],order=['Space Marines','Imperium','Chaos','Xenos'];
  if(!factions.some(f=>f.name===selectedFaction))selectedFaction=factions.find(f=>normalized(f.name)===normalized(context.faction)||(f.aliases||[]).some(a=>normalized(a)===normalized(context.faction)))?.name||factions[0]?.name||'';
  if(!savedLists.some(list=>list.id===listId))listId=savedLists.find(list=>list.id===activeListId)?.id||savedLists[0]?.id||'';
  const opponentDetachments=(catalog.detachments||[]).filter(d=>normalized(d.faction)===normalized(selectedFaction)&&d.enabled!==false&&d.siteExcluded!=='combat-patrol').sort((a,b)=>a.name.localeCompare(b.name));
  if(!opponentDetachments.some(d=>d.name===selectedDetachment))selectedDetachment='';
  bank=selectionBank();
  const available=selectedTypes.reduce((sum,type)=>sum+(bank.counts[type]||0),0),emptyTypes=selectedTypes.filter(type=>!bank.counts[type]);
  const factionField=`<label>Faction<select name="practice_faction">${[...order,'Other'].map(group=>{const entries=factions.filter(f=>group==='Other'?!order.includes(f.group):f.group===group).sort((a,b)=>a.name.localeCompare(b.name));return entries.length?`<optgroup label="${group}">${entries.map(f=>`<option ${f.name===selectedFaction?'selected':''}>${e(f.name)}</option>`).join('')}</optgroup>`:'';}).join('')}</select></label>`;
  const detachmentField=`<label>Detachment (optional)<select name="practice_detachment"><option value="">All detachments</option>${opponentDetachments.map(d=>`<option value="${e(d.name)}" ${d.name===selectedDetachment?'selected':''}>${e(d.name)}</option>`).join('')}</select></label>`;
  const listField=`<label>Army list<select name="practice_list" ${savedLists.length?'':'disabled'}>${savedLists.length?[...savedLists].sort((a,b)=>a.army.name.localeCompare(b.army.name)).map(list=>`<option value="${e(list.id)}" ${list.id===listId?'selected':''}>${e(list.army.name)} — ${e(list.army.faction)}</option>`).join(''):'<option value="">No saved lists yet</option>'}</select></label>`;
  return `<section class="practice-page"><header class="heading"><div><span class="eyebrow">${goal==='opponent'?'OPPONENT PRACTICE':'RECALL PRACTICE'}</span><h1 id="practice-title" tabindex="-1">${goal==='opponent'?'Know what you’re facing.':'Know it by heart.'}</h1><p>${goal==='opponent'?'Learn an unfamiliar army’s effects, units and timing windows.':'Learn what your units can do. Match rule text to a unit, or choose other practice types.'}</p></div></header><form id="practice-setup" class="practice-setup"><label>Practice focus<select name="practice_goal"><option value="army" ${goal==='army'?'selected':''}>Learn my army</option><option value="opponent" ${goal==='opponent'?'selected':''}>Prepare for an opponent</option></select></label>${goal==='opponent'?factionField+detachmentField:`<label>Quiz content<select name="practice_scope"><option value="faction" ${scope==='faction'?'selected':''}>Whole faction</option><option value="list" ${scope==='list'?'selected':''} ${savedLists.length?'':'disabled'}>My saved army list</option></select></label>${scope==='list'?listField:factionField}<div class="practice-list-actions"><button type="button" class="outline" data-action="list-library">My saved lists</button><span>Import or create lists in My army.</span></div>`}<fieldset class="practice-type-picker"><legend>Question types</legend><p>Choose one or more.</p><div class="practice-type-options">${Object.entries(modeLabels()).filter(([id])=>id!=='mixed').map(([id,label])=>`<label><input type="checkbox" name="practice_modes" value="${id}" ${selectedTypes.includes(id)?'checked':''}><span>${e(label)}<small>${bank.counts[id]} available</small></span></label>`).join('')}</div><div class="practice-type-actions"><button type="button" class="text-button" data-practice-action="all-types">Select all</button><button type="button" class="text-button" data-practice-action="no-types">Clear</button></div></fieldset><label>Questions<select name="practice_length">${[5,10,20].map(n=>`<option ${length===n?'selected':''}>${n}</option>`).join('')}</select></label><p class="practice-note">${goal==='opponent'?'Questions cover the chosen opponent faction'+(selectedDetachment?' and detachment, including faction-wide rules.':', across all detachments.')+' Rule wording uses the opponent as “you”; timing answer labels use your perspective. Rules flagged for source review or marked reference-only are skipped.':scope==='list'?'Units and answers come from your saved list, with rules for its selected detachments and enhancements. Repeated squads count once.':'Questions and all four choices stay within the selected faction.'} Unit-matching questions show the rule text without its title; the rule name is revealed after answering. Timing questions include phase, player turn and trigger window; unclear, reference-only and multiple-window timings are skipped. Incomplete summaries and unknown stats are skipped. Each question needs four valid choices.</p>${scope==='list'&&bank.unmatchedUnits.length?`<p class="practice-note">Catalog unit data is still needed for: ${e(bank.unmatchedUnits.join(', '))}.</p>`:''}${emptyTypes.length?`<p class="practice-note">No eligible questions for: ${e(emptyTypes.map(type=>modeLabels()[type]).join(', '))}. Available selected types will be used.</p>`:''}${available&&available<length?`<p class="practice-note">This set will use the ${available} available questions without repeats.</p>`:''}${!selectedTypes.length?'<p class="practice-note" role="status">Choose at least one question type.</p>':!available?'<p class="practice-note" role="status">There are not enough distinct answers yet. Choose other question types or update your list’s catalog coverage.</p>':''}<p class="practice-error" role="status">${e(error)}</p><button type="submit" class="primary" ${available&&selectedTypes.length?'':'disabled'}>Start practice <span aria-hidden="true">→</span></button></form></section>`;
 }

 function explanation(q){
  let reference=q.review,note='';
  if(session.perspective==='opponent'){
   note='<p class="practice-note">Rule text is written for the opponent: “your” refers to their army. Timing labels below are from your perspective.</p>';
   if(reference?.rule){const r=reference.rule,flip=t=>t==='you'?'opponent':t==='opponent'?'you':'either';reference={...reference,rule:{...r,turn:flip(r.turn),...(r.timings?{timings:r.timings.map(t=>({...t,turn:flip(t.turn)}))}:{}),triggerText:''}};if(r.triggerText)note+='<p class="practice-note">Source trigger (opponent wording): '+e(r.triggerText)+'</p>';}
  }
  if(q.review&&root.WarPlannerStudyCards)return note+'<div class="practice-explanation">'+root.WarPlannerStudyCards.reviewCard(reference,{sources:root.WarPlanLessons?.sources||{}})+'</div>';return note+`<div class="practice-explanation"><p>${e(q.explanation.summary)}</p>${q.explanation.conditions.length?`<ul>${q.explanation.conditions.map(c=>`<li>${e(c)}</li>`).join('')}</ul>`:''}<small>${e(q.explanation.sourceLabel)}${q.explanation.sourceUrl?` · <a href="${e(q.explanation.sourceUrl)}" target="_blank" rel="noopener noreferrer">Source</a>`:''}</small></div>`;}
 function question(){
  const q=session.questions[session.index],answer=session.answers[session.index],correct=q.options.find(o=>o.id===q.correct),score=session.answers.filter(a=>a.correct).length;
  return `<section class="practice-page"><div class="practice-top"><span>${e(scopeLabel())} · ${session.types.length>1?'Custom mix':e(modeLabels()[session.mode])}</span><button type="button" class="outline practice-reset-button" data-practice-action="reset">New practice set</button></div><div class="practice-progress"><span>Question ${session.index+1} of ${session.questions.length}</span><span>${score} correct / ${session.answers.length} answered</span></div><article class="practice-card"><span class="rule-badge rule-${e(q.category)}">${e(Q.categories[q.category]||'Unit stat')}</span><h1 id="practice-title" tabindex="-1">${e(q.prompt)}</h1><p class="practice-clue">${e(q.clue)}</p>${session.perspective==='opponent'?'<p class="practice-note">Rule wording belongs to the opponent. Timing choices use your perspective.</p>':''}<div class="practice-options" aria-label="Answer choices">${q.options.map((option,i)=>`<button type="button" class="practice-option ${answer?(option.id===q.correct?'practice-correct':option.id===answer.id?'practice-incorrect':''):''}" data-practice-answer="${e(option.id)}" ${answer?'disabled':''}><span aria-hidden="true">${'ABCD'[i]}</span><span>${e(option.label)}${option.description?`<small class="practice-option-description">${e(option.description)}</small>`:''}</span>${answer&&(option.id===q.correct||option.id===answer.id)?`<strong>${option.id===q.correct?'✓ Correct':'× Your answer'}</strong>`:''}</button>`).join('')}</div>${answer?`<div class="practice-feedback"><p role="status"><strong>${answer.correct?'Correct.':'The correct answer is '+e(correct.label)+'.'}</strong></p>${explanation(q)}</div><button type="button" class="primary practice-next" data-practice-action="next">${session.index+1===session.questions.length?'See results':'Next question'} <span aria-hidden="true">→</span></button><div class="practice-report-container" data-report-container>${root.WarPlannerReports?.practiceForQuestion(q)||''}</div>`:''}</article></section>`;
 }
 function results(){const score=session.answers.filter(a=>a.correct).length,missed=session.questions.filter((_q,i)=>!session.answers[i].correct);return `<section class="practice-page"><header class="heading"><div><span class="eyebrow">SET COMPLETE · ${e(scopeLabel())}</span><h1 id="practice-title" tabindex="-1">${score} of ${session.questions.length} correct</h1><p>${missed.length?'Revisit the ones that need another look.':'Every answer correct. Try a new set to keep practising.'}</p></div></header><div class="button-row">${missed.length?'<button type="button" class="primary" data-practice-action="retry-missed">Retry missed questions</button>':''}<button type="button" class="outline" data-practice-action="again">Another set</button><button type="button" class="outline" data-practice-action="reset">Change practice</button></div><div class="practice-type-results">${session.types.map(type=>{const indices=session.questions.map((q,i)=>q.mode===type?i:-1).filter(i=>i>=0);return `<p>${e(modeLabels()[type])}: ${indices.filter(i=>session.answers[i]?.correct).length} / ${indices.length}</p>`;}).join('')}</div>${missed.length?`<details class="practice-review"><summary>Review missed questions (${missed.length})</summary>${missed.map(q=>`<article><h2>${e(q.prompt)}</h2><p>${e(q.clue)}</p><strong>${e(q.options.find(o=>o.id===q.correct).label)}</strong>${explanation(q)}</article>`).join('')}</details>`:''}<p class="practice-note">This score is for this set only.</p></section>`;}
 function start(form=null){try{if(form)readSetup(form);bank=selectionBank(true);session=Q.createSession(bank,{types:selectedTypes,count:length});if(!session.questions.length){session=null;error='There are not enough distinct answers. Choose other question types or a different list.';}else error='';}catch(failure){session=null;error=failure.message;}refresh();}
 document.addEventListener('change',event=>{const form=event.target.closest?.('#practice-setup');if(!form)return;const control={name:event.target.name,value:event.target.value};readSetup(form);error='';refresh(control);});
 document.addEventListener('submit',event=>{if(event.target.id!=='practice-setup')return;event.preventDefault();start(event.target);});
 document.addEventListener('click',event=>{const b=event.target.closest?.('[data-practice-answer],[data-practice-action]');if(!b)return;if(b.dataset.practiceAnswer!==undefined){if(session&&Q.answer(session,b.dataset.practiceAnswer))refresh();return;}const action=b.dataset.practiceAction;if(action==='all-types'||action==='no-types'){selectedTypes=action==='all-types'?Object.keys(modeLabels()).filter(type=>type!=='mixed'):[];error='';refresh();}if(action==='retry-missed'&&session){session=Q.retryMissed(session);refresh();}if(action==='reset'){session=null;error='';refresh();}if(action==='next'&&session?.answers.length===session.index+1){session.index++;refresh();}if(action==='again'&&session)start();});
 root.WarPlannerPracticePage={render,reset(){bankCache=null;goal='army';selectedDetachment='';selectedFaction='';scope='faction';listId='';selectedTypes=['units','timing'];savedLists=[];activeListId='';length=10;session=null;bank=null;catalog=null;rules=null;error='';}};
})(window);
